const { chromium } = require("playwright");
const fs = require("node:fs");
const path = require("node:path");
const target = process.env.TARGET_URL || "https://irpa-digital-board-governance.web.app";
const out = path.resolve("hero-layout-evidence"); fs.mkdirSync(out,{recursive:true});
const report={target,testedAt:new Date().toISOString(),cache:{},viewports:[],interactions:{},consoleErrors:[],pageErrors:[],dashboardAccessible:false};
(async()=>{const browser=await chromium.launch({headless:true,args:["--no-sandbox"]});try{
 const page=await browser.newPage({viewport:{width:1366,height:768},deviceScaleFactor:1});
 page.on("console",m=>{if(m.type()==="error")report.consoleErrors.push({text:m.text(),location:m.location()})});page.on("pageerror",e=>report.pageErrors.push(String(e)));
 const response=await page.goto(target,{waitUntil:"domcontentloaded",timeout:60000});report.httpStatus=response?.status();await page.waitForTimeout(5000);
 const html=await page.content();
 report.htmlScriptAssets=await page.locator("script[src]").evaluateAll(es=>es.map(e=>e.getAttribute("src")));
 report.htmlStylesheetAssets=await page.locator('link[rel="stylesheet"]').evaluateAll(es=>es.map(e=>e.getAttribute("href")));
 report.cache.builtAssets=[];
 for(const u of [...report.htmlScriptAssets,...report.htmlStylesheetAssets]){
  try{const r=await page.request.get(new URL(u,target).toString(),{timeout:20000});const t=await r.text();report.cache.builtAssets.push({url:u,status:r.status(),bytes:t.length,hasWeatherSelector:t.includes("google-weather-panel"),hasHeroGrid:t.includes("minmax(200px,260px)")||t.includes("minmax(200px, 260px)"),hasWeatherBlue:t.includes("#2563eb")||t.includes("37,99,235"),hasLandscapeRules:t.includes("grid-template-areas")&&t.includes("authority")})}
  catch(e){report.cache.builtAssets.push({url:u,error:String(e)})}
 }

report.cache.indexVersion=html.match(/\/src\/main\.jsx\?v=([^"'&]+)/)?.[1]||null;
 try{const r=await page.request.get(new URL("/sw.js",target).toString(),{timeout:20000});const t=await r.text();report.cache.swHttpStatus=r.status();report.cache.serviceWorkerVersion=t.match(/CACHE_NAME\s*=\s*["']([^"']+)/)?.[1]||null}catch(e){report.cache.swFetchError=String(e)}
 report.title=await page.title();report.authScreenVisible=await page.locator(".auth-screen").count()>0;
 report.dashboardAccessible=await page.locator(".google-weather-panel").count()>0&&await page.locator(".topbar-access-category").count()>0&&await page.locator(".topbar-heading-row").count()>0;
 if(!report.dashboardAccessible){for(const vp of [{width:1366,height:768},{width:1920,height:1080}]){await page.setViewportSize(vp);await page.waitForTimeout(300);await page.screenshot({path:path.join(out,"auth-screen-"+vp.width+"x"+vp.height+".png"),fullPage:true})}report.dashboardBlocker=report.authScreenVisible?"Anonymous browser landed on authentication screen; authenticated dashboard session unavailable.":"Dashboard/weather selectors not found on the live page.";report.dashboardChecks="SKIPPED — production authentication required; no credentials/session were supplied to this isolated browser."}
 else{
  for(const vp of [{width:1366,height:768},{width:1920,height:1080}]){
   await page.setViewportSize(vp);await page.waitForTimeout(1000);
   const measure=()=>page.evaluate(()=>{const box=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom}};const style=e=>{const s=getComputedStyle(e);return{color:s.color,backgroundColor:s.backgroundColor,borderColor:s.borderColor,boxShadow:s.boxShadow,display:s.display,gridTemplateColumns:s.gridTemplateColumns}};const w=document.querySelector(".google-weather-panel"),a=document.querySelector(".topbar-access-category"),t=document.querySelector(".topbar-title-block"),h=document.querySelector("header.dashboard-topbar"),m=[...document.querySelectorAll(".live-weather-metrics>span")],strip=document.querySelector(".live-weather-days");return{viewport:{width:innerWidth,height:innerHeight},weather:box(w),weatherStyle:style(w),access:box(a),accessStyle:style(a),title:box(t),header:box(h),metrics:m.map(e=>({text:e.innerText,top:e.getBoundingClientRect().top,left:e.getBoundingClientRect().left,box:box(e),color:getComputedStyle(e).color})),forecast:[...document.querySelectorAll(".live-weather-day")].map((e,i)=>({index:i,text:e.innerText,box:box(e),fullyVisible:!!strip&&e.getBoundingClientRect().left>=strip.getBoundingClientRect().left-1&&e.getBoundingClientRect().right<=strip.getBoundingClientRect().right+1,clipped:!!strip&&e.getBoundingClientRect().right>strip.getBoundingClientRect().right+1})),forecastStrip:strip?{box:box(strip),scrollWidth:strip.scrollWidth,clientWidth:strip.clientWidth,overflowX:getComputedStyle(strip).overflowX,display:getComputedStyle(strip).display}:null,accessText:[...a.querySelectorAll("span,strong,small")].map(e=>({text:(e.innerText||"").trim(),color:getComputedStyle(e).color})).filter(e=>e.text),weatherTextColors:[...w.querySelectorAll("span,strong,small,b")].slice(0,25).map(e=>({text:(e.innerText||"").trim(),color:getComputedStyle(e).color}))}}); 
   const initial=await measure();const fb=page.getByRole("button",{name:/^(Forecast|Less)$/}).first();if(await fb.count()&&(await fb.innerText()).trim()!=="Less")await fb.click();await page.waitForTimeout(500);const open=await measure();const shot=path.join(out,"hero-"+vp.width+"x"+vp.height+".png");await page.screenshot({path:shot,fullPage:true});report.viewports.push({beforeForecastOpen:initial,afterForecastOpen:open,screenshot:shot});
  }
  const fb=page.getByRole("button",{name:/^(Forecast|Less)$/}).first();if(await fb.count()){const b=(await fb.innerText()).trim();await fb.click();const a=(await fb.innerText()).trim();report.interactions.forecastToggle={before:b,after:a,passed:b!==a}}
  const city=page.locator(".live-weather-location-name strong").first();if(await city.count()){const b=await city.innerText();const n=page.getByRole("button",{name:"Next weather location"});if(await n.count()){await n.click();await page.waitForTimeout(300);const a=await city.innerText();report.interactions.weatherNext={before:b,after:a,passed:b!==a}}const p=page.getByRole("button",{name:"Previous weather location"});if(await p.count()){const b2=await city.innerText();await p.click();await page.waitForTimeout(300);const a2=await city.innerText();report.interactions.weatherPrevious={before:b2,after:a2,passed:b2!==a2}}}
  const cb=await city.innerText().catch(()=>null);await page.waitForTimeout(8500);const ca=await city.innerText().catch(()=>null);report.interactions.weatherLiveRotation={before:cb,after:ca,passed:!!cb&&!!ca&&cb!==ca};
  const sel=page.getByLabel("Navigate to a sub-portal within the current portal");report.interactions.pageSelector={found:await sel.count()>0};if(await sel.count()){const opts=await sel.locator("option").evaluateAll(os=>os.map(o=>({value:o.value,text:o.textContent})));report.interactions.pageSelector.options=opts.length;const old=await sel.inputValue(),next=opts.find(o=>o.value!==old);if(next){await sel.selectOption(next.value);await page.waitForTimeout(500);report.interactions.pageSelector.passed=(await sel.inputValue())===next.value;report.interactions.pageSelector.selected=next.value}}
  const nxt=page.getByRole("button",{name:/^Next to /}).first();if(await nxt.count()){const b=await page.locator(".page-back-next-status strong").innerText().catch(()=>null);await nxt.click();await page.waitForTimeout(500);const a=await page.locator(".page-back-next-status strong").innerText().catch(()=>null);report.interactions.navigationNext={before:b,after:a,passed:!!a&&a!==b};const back=page.getByRole("button",{name:/^Back to /}).first();if(await back.count()){await back.click();await page.waitForTimeout(500);report.interactions.navigationBack={passed:(await page.locator(".page-back-next-status strong").innerText().catch(()=>null))===b}}}
  report.interactions.sessionRecovery={visible:await page.getByText("SESSION RECOVERY AVAILABLE",{exact:true}).count()>0,localStorageKeyPresent:await page.evaluate(()=>!!localStorage.getItem("irpaSessionRecovery"))};
 }
 fs.writeFileSync(path.join(out,"report.json"),JSON.stringify(report,null,2));console.log("IRPA_HERO_BROWSER_REPORT_BEGIN");console.log(JSON.stringify(report,null,2));console.log("IRPA_HERO_BROWSER_REPORT_END");
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
